ROOT = Path(r"C:\PhoCap")
SERVICE = ROOT / "app" / "services" / "school_merger_service.py"
TEMPLATE = ROOT / "app" / "templates" / "data_tools" / "school_merger.html"
PLAN_FILE = ROOT / "data" / "school_merger_approved_plans.json"
DB_PATH = ROOT / "data" / "phocap.db"
EXPORTS = ROOT / "exports"

EXPECTED_SERVICE_SHA = "71b89cb32fd870e65099591836fd4148e31340d7b1f6fb27add343676918a97d"
EXPECTED_TEMPLATE_SHA = "a7d396fe45e2517f9d4fea260ec24029980078bb31eef7f368070ca1f73ea058"
EXPECTED_PLAN_SHA = "004fdaa536f8229dcfce51d02031941aa639a7cace8927e4b5cb3c86985d30cf"

NEW_SERVICE_SHA = "414fb49a4c5f4fed7b571cc55df381678fe660cd8a675ecaa2f6fd70ebd7827a"
NEW_TEMPLATE_SHA = "77c008a3bcf29f1ce7f295ed1a397e83b8d092acdeff6b874afec2faeec101b6"

SERVICE_ZLIB_B64 = """"""
TEMPLATE_ZLIB_B64 = """"""

MARKER = "# === V13_5_2_CURRENT_FUTURE_SCOPE ==="


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def db_health() -> tuple[str, int]:
    uri = DB_PATH.resolve().as_uri() + "?mode=ro"
    con = sqlite3.connect(uri, uri=True, timeout=30)
    try:
        con.execute("PRAGMA query_only=ON")
        integrity = str(
            con.execute("PRAGMA integrity_check").fetchone()[0]
        )
        fk = len(
            con.execute("PRAGMA foreign_key_check").fetchall()
        )
        return integrity, fk
    finally:
        con.close()


def load_plans() -> list[dict]:
    payload = json.loads(
        PLAN_FILE.read_text(encoding="utf-8")
    )
    plans = payload.get("plans")
    if not isinstance(plans, list):
        raise RuntimeError("Plan JSON không có mảng plans.")
    return [p for p in plans if isinstance(p, dict)]


def validate_registry() -> tuple[int, int, int]:
    plans = load_plans()
    qd = [
        p for p in plans
        if (
            str(p.get("id") or "").startswith("QD3805-")
            or "3805" in str(p.get("document_code") or "")
        )
    ]
    qd_completed = [
        p for p in qd
        if str(p.get("status") or "").upper() == "COMPLETED"
    ]
    province = [
        p for p in plans
        if str(p.get("document_code") or "")
        == "NGUON-SAP-NHAP-TOAN-TINH"
    ]
    province_approved = [
        p for p in province
        if str(p.get("status") or "").upper() == "APPROVED"
    ]

    if len(plans) != 418:
        raise RuntimeError(
            f"Registry phải có 418 plan; hiện={len(plans)}."
        )
    if len(qd) != 6 or len(qd_completed) != 6:
        raise RuntimeError(
            f"QĐ3805 phải đúng 6 COMPLETED; "
            f"qd={len(qd)}, completed={len(qd_completed)}."
        )
    if len(province) != 412 or len(province_approved) != 412:
        raise RuntimeError(
            f"Plan toàn tỉnh phải đúng 412 APPROVED; "
            f"province={len(province)}, approved={len(province_approved)}."
        )

    return len(plans), len(qd_completed), len(province_approved)


def year_scope() -> tuple[list[int], list[int], dict[int, str]]:
    uri = DB_PATH.resolve().as_uri() + "?mode=ro"
    con = sqlite3.connect(uri, uri=True, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA query_only=ON")
        rows = con.execute(
            "SELECT id,code,name FROM school_years ORDER BY id"
        ).fetchall()
    finally:
        con.close()

    starts: dict[int, int] = {}
    labels: dict[int, str] = {}

    for row in rows:
        text = str(row["code"] or row["name"] or "")
        match = re.search(r"(\d{4})\D+(\d{4})", text)
        if not match:
            raise RuntimeError(
                f"Không phân loại được năm học id={row['id']}: {text!r}"
            )
        starts[int(row["id"])] = int(match.group(1))
        labels[int(row["id"])] = text

    if labels.get(2) != "2026-2027":
        raise RuntimeError(
            f"school_year_id=2 không còn là 2026-2027: {labels.get(2)}"
        )

    selected_start = starts[2]
    move_ids = sorted(
        yid for yid, start in starts.items()
        if start >= selected_start
    )
    past_ids = sorted(
        yid for yid, start in starts.items()
        if start < selected_start
    )

    if move_ids != [2, 8]:
        raise RuntimeError(
            f"CURRENT+FUTURE dự kiến [2,8], thực tế={move_ids}."
        )

    return move_ids, past_ids, labels


def future_scope_rows(
    province_plans: list[dict],
    future_year_ids: list[int],
) -> list[dict]:
    if not future_year_ids:
        return []

    source_ids = sorted({
        int(sid)
        for p in province_plans
        for sid in (p.get("source_school_ids") or [])
    })
    if not source_ids:
        return []

    uri = DB_PATH.resolve().as_uri() + "?mode=ro"
    con = sqlite3.connect(uri, uri=True, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA query_only=ON")
        tables = [
            str(r["name"])
            for r in con.execute(
                "SELECT name FROM sqlite_master "
                "WHERE type='table' AND name NOT LIKE 'sqlite_%' "
                "ORDER BY name"
            ).fetchall()
        ]

        result: list[dict] = []
        for table in tables:
            cols = {
                str(r["name"])
                for r in con.execute(
                    f'PRAGMA table_info("{table}")'
                ).fetchall()
            }
            if not {"school_id", "school_year_id"} <= cols:
                continue

            sql = (
                f'SELECT school_year_id,COUNT(*) AS n '
                f'FROM "{table}" '
                f'WHERE school_id IN ({",".join("?" for _ in source_ids)}) '
                f'AND school_year_id IN ({",".join("?" for _ in future_year_ids)}) '
                f'GROUP BY school_year_id'
            )
            rows = con.execute(
                sql,
                [*source_ids, *future_year_ids],
            ).fetchall()

            for row in rows:
                result.append({
                    "table": table,
                    "school_year_id": int(row["school_year_id"]),
                    "rows": int(row["n"]),
                })

        return result
    finally:
        con.close()


def main() -> int:
    print("=" * 126)
    print("V13.5.2 - CURRENT + FUTURE TRÊN ĐÚNG ENGINE HIỆN TẠI")
    print("=" * 126)
    print("Database nghiệp vụ: KHÔNG THAY ĐỔI")
    print("Plan JSON: KHÔNG THAY ĐỔI")

    for path in (SERVICE, TEMPLATE, PLAN_FILE, DB_PATH):
        if not path.exists():
            raise RuntimeError(f"Không tìm thấy: {path}")

    integrity_before, fk_before = db_health()
    if integrity_before.lower() != "ok" or fk_before != 0:
        raise RuntimeError(
            f"DB preflight lỗi: integrity={integrity_before}, FK={fk_before}"
        )

    plan_sha_before = sha(PLAN_FILE)
    if plan_sha_before != EXPECTED_PLAN_SHA:
        raise RuntimeError(
            "Plan JSON đã thay đổi so với ZIP V13.5.1; dừng để tránh cài "
            "trên nền khác.\n"
            f"SHA hiện={plan_sha_before}\n"
            f"SHA cần={EXPECTED_PLAN_SHA}"
        )

    total_plans, qd_count, approved_count = validate_registry()
    move_ids, past_ids, labels = year_scope()

    current_service_sha = sha(SERVICE)
    current_template_sha = sha(TEMPLATE)

    if MARKER in SERVICE.read_text(encoding="utf-8-sig"):
        if current_service_sha != NEW_SERVICE_SHA:
            raise RuntimeError(
                "Service có marker V13.5.2 nhưng SHA không đúng bản chuẩn."
            )
        already_installed = True
    else:
        if current_service_sha != EXPECTED_SERVICE_SHA:
            raise RuntimeError(
                "Service hiện tại không còn đúng bản V13.5.1 đã gửi.\n"
                f"SHA hiện={current_service_sha}\n"
                f"SHA cần={EXPECTED_SERVICE_SHA}"
            )
        if current_template_sha != EXPECTED_TEMPLATE_SHA:
            raise RuntimeError(
                "Template hiện tại không còn đúng bản V13.5.1 đã gửi.\n"
                f"SHA hiện={current_template_sha}\n"
                f"SHA cần={EXPECTED_TEMPLATE_SHA}"
            )
        already_installed = False

    province_plans = [
        p for p in load_plans()
        if str(p.get("document_code") or "")
        == "NGUON-SAP-NHAP-TOAN-TINH"
    ]
    future_before = future_scope_rows(
        province_plans,
        [x for x in move_ids if x != 2],
    )

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = EXPORTS / f"backup_source_v13_5_2_{stamp}"
    backup.mkdir(parents=True, exist_ok=False)

    for path in (SERVICE, TEMPLATE):
        dst = backup / path.relative_to(ROOT)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dst)

    try:
        if not already_installed:
            service_bytes = zlib.decompress(
                base64.b64decode(
                    SERVICE_ZLIB_B64.encode("ascii")
                )
            )
            template_bytes = zlib.decompress(
                base64.b64decode(
                    TEMPLATE_ZLIB_B64.encode("ascii")
                )
            )

            if hashlib.sha256(service_bytes).hexdigest() != NEW_SERVICE_SHA:
                raise RuntimeError("Payload service V13.5.2 sai SHA.")
            if hashlib.sha256(template_bytes).hexdigest() != NEW_TEMPLATE_SHA:
                raise RuntimeError("Payload template V13.5.2 sai SHA.")

            SERVICE.write_bytes(service_bytes)
            TEMPLATE.write_bytes(template_bytes)

        # Hậu kiểm source.
        service_text = SERVICE.read_text(encoding="utf-8")
        template_text = TEMPLATE.read_text(encoding="utf-8")

        ast.parse(service_text)
        py_compile.compile(str(SERVICE), doraise=True)

        required = [
            MARKER,
            "def _year_scope_ids(",
            "def _count_rows_for_year_ids(",
            "MOVE_CLASSES_CURRENT_FUTURE",
            "MOVE_ENROLLMENTS_CURRENT_FUTURE",
            "MOVE_CURRENT_FUTURE_AND_ROLLOVER_STAFF",
            "MOVE_CURRENT_FUTURE_BY_INDIRECT_TRACE",
            "CURRENT/FUTURE",
            "year_ids=move_year_ids",
        ]
        missing = [x for x in required if x not in service_text]
        if missing:
            raise RuntimeError(
                "Service V13.5.2 thiếu marker: " + repr(missing)
            )

        from jinja2 import Environment
        Environment().parse(template_text)

        if "Năm hiện hành + tương lai sẽ xử lý" not in template_text:
            raise RuntimeError(
                "Template chưa đổi nhãn CURRENT + FUTURE."
            )

        if sha(SERVICE) != NEW_SERVICE_SHA:
            raise RuntimeError("SHA service sau cài không đúng.")
        if sha(TEMPLATE) != NEW_TEMPLATE_SHA:
            raise RuntimeError("SHA template sau cài không đúng.")

        # Plan JSON phải tuyệt đối không đổi.
        if sha(PLAN_FILE) != plan_sha_before:
            raise RuntimeError("Plan JSON đã thay đổi ngoài dự kiến.")

        integrity_after, fk_after = db_health()
        if integrity_after.lower() != "ok" or fk_after != 0:
            raise RuntimeError(
                f"DB hậu kiểm lỗi: integrity={integrity_after}, FK={fk_after}"
            )

        total_after, qd_after, approved_after = validate_registry()

        report = backup / "00_KET_QUA_V13_5_2.txt"
        report.write_text(
            "\n".join([
                "V13.5.2 - CURRENT + FUTURE TRÊN ĐÚNG ENGINE HIỆN TẠI",
                "=" * 100,
                "STATUS=SUCCESS",
                f"Service nền cũ={EXPECTED_SERVICE_SHA}",
                f"Service mới={NEW_SERVICE_SHA}",
                f"Template mới={NEW_TEMPLATE_SHA}",
                "Database nghiệp vụ=KHÔNG THAY ĐỔI",
                "Plan JSON=KHÔNG THAY ĐỔI",
                f"PAST year ids={past_ids}",
                f"CURRENT+FUTURE year ids={move_ids}",
                f"QĐ3805 COMPLETED={qd_after}",
                f"Plan toàn tỉnh APPROVED={approved_after}",
                f"Future rows tại 412 source={sum(x['rows'] for x in future_before)}",
                f"Future detail={future_before}",
                f"DB integrity={integrity_after}",
                f"DB FK={fk_after}",
                f"Backup source={backup}",
            ]),
            encoding="utf-8",
        )

        zip_path = ROOT / f"ket_qua_v13_5_2_{stamp}.zip"
        with zipfile.ZipFile(
            zip_path,
            "w",
            compression=zipfile.ZIP_DEFLATED,
        ) as zf:
            zf.write(report, arcname=report.name)

        print()
        print("=" * 126)
        print("CÀI V13.5.2 THÀNH CÔNG")
        print("=" * 126)
        print(f"PAST year ids: {past_ids}")
        print(f"CURRENT + FUTURE year ids: {move_ids}")
        print(
            "Future rows tại 412 source: "
            f"{sum(x['rows'] for x in future_before)}"
        )
        for item in future_before:
            print(
                f"  {item['table']} | "
                f"year_id={item['school_year_id']} | "
                f"rows={item['rows']}"
            )
        print(f"QĐ3805 COMPLETED: {qd_after}")
        print(f"Plan toàn tỉnh APPROVED: {approved_after}")
        print("Database nghiệp vụ: KHÔNG THAY ĐỔI")
        print("Plan JSON: KHÔNG THAY ĐỔI")
        print(f"DB integrity: {integrity_after}")
        print(f"DB FK errors: {fk_after}")
        print(f"Backup source: {backup}")
        print(f"ZIP kết quả: {zip_path}")
        return 0

    except Exception:
        for path in (SERVICE, TEMPLATE):
            src = backup / path.relative_to(ROOT)
            if src.exists():
                path.parent.mkdir(
                    parents=True,
                    exist_ok=True,
                )
                shutil.copy2(src, path)
        raise


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print()
        print("=" * 126)
        print("V13.5.2 DỪNG AN TOÀN - ĐÃ KHÔI PHỤC SOURCE")
        print("=" * 126)
        print(repr(exc))
        print("Database nghiệp vụ: KHÔNG THAY ĐỔI")
        print("Plan JSON: KHÔNG THAY ĐỔI")
        raise SystemExit(2)
